using sv_e411f91753804e4da85eece0b7625bd5.Models;

namespace sv_e411f91753804e4da85eece0b7625bd5.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_e411f91753804e4da85eece0b7625bd5.Models;

namespace sv_e411f91753804e4da85eece0b7625bd5.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", 30),
            new(2, "Spaghetti Carbonara", "Traditional Roman pasta with egg, pecorino, guanciale, and black pepper.", 25),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Pad Thai", "Stir-fried rice noodles with shrimp, peanuts, bean sprouts, and tamarind sauce.", 35),
            new(5, "Green Curry", "Aromatic coconut curry with Thai basil, bamboo shoots, and chicken.", 40),
            new(6, "Tom Yum Soup", "Hot and sour soup with lemongrass, galangal, shrimp, and mushrooms.", 20),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion on corn tortillas.", 50),
            new(8, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(9, "Chicken Enchiladas", "Corn tortillas filled with chicken, topped with red chili sauce and cheese.", 45),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call.
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_e411f91753804e4da85eece0b7625bd5.Models
@using sv_e411f91753804e4da85eece0b7625bd5.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h2>Recipes — Cuisine @CuisineId</h2>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex justify-content-between align-items-center" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm" @onclick="Retry">Retry</button>
    </div>
}

@if (_recipes is null && _isLoading)
{
    <p><em>Loading recipes…</em></p>
}
else if (_recipes is not null)
{
    @if (_isLoading)
    {
        <div class="text-muted mb-2"><small>Refreshing…</small></div>
    }

    var displayed = GetSortedRecipes();
    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in displayed)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _errorMessage;

    private CancellationTokenSource? _loadCts;
    private int _lastLoadedCuisineId;

    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when the cuisine changes, not when sort changes.
        if (_lastLoadedCuisineId == CuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for the previous cuisine.
        await CancelPendingLoadAsync();

        _lastLoadedCuisineId = CuisineId;
        _isLoading = true;
        _errorMessage = null;

        var cts = new CancellationTokenSource();
        _loadCts = cts;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale callback after cancellation.
            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            _recipes = results;
        }
        catch (OperationCanceledException)
        {
            // Expected when the user navigates away or switches cuisine.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            // Only clear loading if this CTS is still the active one.
            if (_loadCts == cts)
            {
                _isLoading = false;
            }
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null)
        {
            return new List<Recipe>();
        }

        return Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
            _ => _recipes,
        };
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
            _loadCts = null;
        }
    }

    public void Dispose()
    {
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = null;
    }
}

