+        }
+        finally
+        {
+            // Only clear loading if this CTS is still the active one.
+            if (_loadCts == cts)
+            {
+                _isLoading = false;
+            }
+        }
+    }
+
+    private async Task Retry()
+    {
+        await LoadRecipesAsync();
+    }
+
+    private List<Recipe> GetSortedRecipes()
+    {
+        if (_recipes is null)
+        {
+            return new List<Recipe>();
+        }
+
+        return Sort?.ToLowerInvariant() switch
+        {
+            "newest" => _recipes.OrderByDescending(r => r.Id).ToList(),
+            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes).ToList(),
+            _ => _recipes,
+        };
+    }
+
+    private async Task CancelPendingLoadAsync()
+    {
+        if (_loadCts is not null)
+        {
+            await _loadCts.CancelAsync();
+            _loadCts.Dispose();
+            _loadCts = null;
+        }
+    }
+
+    public void Dispose()
+    {
+        _loadCts?.Cancel();
+        _loadCts?.Dispose();
+        _loadCts = null;
+    }
+}
